"""Quality checks for folk-rnn-style ABC tunes, on real tunes or tunes generated by a trained run.

The corpus (data/folkrnn/folkrnn.txt) stores one private-use character per ABC token and one tune per line;
data/folkrnn/vocab.json maps the characters back to tokens. Per tune it checks:

    header     the tune starts with exactly one M: token followed by one K: token
    bars       each bar's total duration (unit 1/8, as L:1/8) equals the meter (4/4 = 8, 6/8 = 6, 3/4 = 6,
               2/4 = 4, 9/8 = 9, 12/8 = 12, 3/2 = 12); the first and last bar (pickups) and empty bars are
               skipped. Durations: a note or rest is 1; "2", "/2", "3/2" ... multiply it; ">" makes it 1.5 and
               the next 0.5 ("<" the reverse); "(3" plays the next 3 notes in the time of 2 ("(2" 2 in 3,
               "(4" 4 in 3); a chord [ ... ] counts once with its first note's duration
    repeats    as many :| as |: (a missing opening |: at the tune start is allowed) and as many |2 as |1
    tonic      the last note is a C (every tune in this corpus is transposed to root C)

Usage:
    python3 abc_quality.py --real test                     # the corpus' own test tunes (the ceiling)
    python3 abc_quality.py --run folkrnn_256d6L_ann_base --n 500
    python3 abc_quality.py --run folkrnn_lstm3x512 --ckpt best --n 500 --temperature 1.0
"""

import argparse
import json
import os
import re
from fractions import Fraction

import torch

VOCAB = json.load(open(os.path.join("data", "folkrnn", "vocab.json")))
BARS = {"|", ":|", "|:", "|1", "|2"}
METER = {"M:4/4": 8, "M:6/8": 6, "M:3/4": 6, "M:2/4": 4, "M:9/8": 9, "M:12/8": 12, "M:3/2": 12}
TUPLET = {"(2": Fraction(3, 2), "(3": Fraction(2, 3), "(4": Fraction(3, 4), "(5": Fraction(2, 5),
          "(6": Fraction(2, 6), "(7": Fraction(2, 7), "(9": Fraction(2, 9)}
NOTE = re.compile(r"^[=^_]*[A-Ga-gz][,']*$")
DUR = re.compile(r"^(\d*)(/?)(\d*)$")


def decode(line: str) -> list:
    return [VOCAB[ch] for ch in line if ch in VOCAB]


def duration_factor(tok: str):
    """'2' -> 2, '/2' -> 1/2, '3/2' -> 3/2, '/' -> 1/2; None if tok is not a duration."""
    m = DUR.match(tok)
    if not m or tok == "":
        return None
    num, slash, den = m.groups()
    if not slash:
        return Fraction(int(num)) if num else None
    return Fraction(int(num) if num else 1, int(den) if den else 2)


def bar_lengths(tokens: list) -> list:
    """Duration of every bar (list of Fractions; None for a bar that could not be parsed)."""
    bars, notes, tuplet_left, tuplet_f, pending_next = [], [], 0, Fraction(1), None
    in_chord, chord_dur = False, None
    for tok in tokens:
        if tok in BARS:
            bars.append(sum(notes, Fraction(0)) if notes else None)
            notes = []
            continue
        if tok.startswith(("M:", "K:")):
            continue
        if tok in TUPLET:
            tuplet_left, tuplet_f = int(tok[1:]), TUPLET[tok]
            continue
        if tok == "[":
            in_chord, chord_dur = True, None
            continue
        if tok == "]":
            in_chord = False
            d = chord_dur if chord_dur is not None else Fraction(1)
            notes.append(d)
            continue
        if NOTE.match(tok):
            if in_chord:
                if chord_dur is None:
                    chord_dur = Fraction(1)
                continue
            d = Fraction(1)
            if pending_next is not None:
                d, pending_next = d * pending_next, None
            if tuplet_left > 0:
                d, tuplet_left = d * tuplet_f, tuplet_left - 1
            notes.append(d)
            continue
        if tok in (">", "<"):
            if notes:
                notes[-1] *= Fraction(3, 2) if tok == ">" else Fraction(1, 2)
                pending_next = Fraction(1, 2) if tok == ">" else Fraction(3, 2)
            continue
        f = duration_factor(tok)
        if f is not None:
            if in_chord and chord_dur is not None:
                chord_dur = chord_dur * f
            elif notes:
                notes[-1] *= f
    if notes:
        bars.append(sum(notes, Fraction(0)))
    return bars


def check(tokens: list) -> dict:
    header = len(tokens) >= 2 and tokens[0].startswith("M:") and tokens[1].startswith("K:") and \
        sum(t.startswith("M:") for t in tokens) == 1 and sum(t.startswith("K:") for t in tokens) == 1
    target = METER.get(tokens[0]) if tokens else None
    bars = [b for b in bar_lengths(tokens)[1:-1] if b is not None]
    valid = sum(b == target for b in bars) if target else 0
    opens, closes = tokens.count("|:"), tokens.count(":|")
    repeats = (closes == opens or closes == opens + 1) and tokens.count("|1") == tokens.count("|2")
    last_note = next((t for t in reversed(tokens) if NOTE.match(t) and "z" not in t), "")
    return {"header": header, "bars": len(bars), "valid_bars": valid, "repeats": repeats,
            "tonic": last_note.strip("=^_,'").upper() == "C"}


def summarize(tunes: list, label: str):
    rs = [check(t) for t in tunes if t]
    n = len(rs)
    bars = sum(r["bars"] for r in rs)
    print(f"{label}: {n} tunes | header ok {100 * sum(r['header'] for r in rs) / n:5.1f}% | "
          f"bars with correct length {100 * sum(r['valid_bars'] for r in rs) / max(bars, 1):5.1f}% "
          f"({bars:,} bars) | repeats balanced {100 * sum(r['repeats'] for r in rs) / n:5.1f}% | "
          f"ends on C {100 * sum(r['tonic'] for r in rs) / n:5.1f}% | median length "
          f"{sorted(len(t) for t in tunes if t)[n // 2]} tokens", flush=True)


@torch.no_grad()
def generate(run: str, ckpt: str, n: int, temperature: float, max_len: int = 600, batch: int = 100) -> list:
    from models import model_from_config
    config = json.load(open(os.path.join("runs", run, "config.json")))
    state = torch.load(os.path.join("runs", run, f"{ckpt}.pt"), map_location="cpu", weights_only=False)
    state = state.get("model", state)
    chars = config["chars"]
    stoi = {c: i for i, c in enumerate(chars)}
    nl = stoi["\n"]
    if config.get("model_type") == "lstm":
        from lstm_baseline import LSTMLM
        model = LSTMLM(config["vocab_size"], config["hidden"], config["layers"], config["dropout"])
    else:
        model = model_from_config(config, config["block_size"])
    model.load_state_dict(state)
    model.cuda().eval()
    block = config["block_size"]
    tunes = []
    torch.manual_seed(0)
    while len(tunes) < n:
        b = min(batch, n - len(tunes))
        ids = torch.full((b, 1), nl, device="cuda")
        done = torch.zeros(b, dtype=torch.bool, device="cuda")
        state_ = None
        with torch.autocast("cuda", dtype=torch.bfloat16):
            for _ in range(max_len):
                if config.get("model_type") == "lstm":
                    logits, state_ = model(ids[:, -1:], state_, return_state=True)
                    logits = logits[:, -1]
                else:
                    logits = model(ids[:, -block:])[:, -1]
                nxt = torch.multinomial(torch.softmax(logits.float() / temperature, -1), 1)
                nxt[done] = nl
                ids = torch.cat([ids, nxt], 1)
                done |= nxt[:, 0] == nl
                if done.all():
                    break
        for row in ids[:, 1:].tolist():
            text = "".join(chars[i] for i in row)
            tunes.append(decode(text.split("\n")[0]))
    return tunes


def main():
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--real", choices=("train", "val", "test"), help="score the corpus' own tunes of this split")
    p.add_argument("--run", help="generate from this run and score the tunes")
    p.add_argument("--ckpt", default="best")
    p.add_argument("--n", type=int, default=500)
    p.add_argument("--temperature", type=float, default=1.0)
    p.add_argument("--save", default="", help="write the generated tunes (decoded ABC, one per line) here")
    args = p.parse_args()
    if args.real:
        from char_data import CharDataset
        d = CharDataset(os.path.join("data", "folkrnn", "folkrnn.txt"), 0.05, 0.05)
        text = d.decode(d.splits[args.real].tolist())
        tunes = [decode(line) for line in text.split("\n")[1:-1]]   # drop the partial first / last tune
        summarize(tunes, f"real {args.real} tunes")
    if args.run:
        tunes = generate(args.run, args.ckpt, args.n, args.temperature)
        summarize(tunes, f"{args.run} ({args.ckpt}, temperature {args.temperature})")
        if args.save:
            open(args.save, "w").write("\n".join(" ".join(t) for t in tunes) + "\n")


if __name__ == "__main__":
    main()
